package com.geekmall.search;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class SearchConsumerIdempotencyTest{@Test void duplicateEventDoesNotWriteElasticsearch(){ElasticsearchGateway es=mock(ElasticsearchGateway.class);JdbcTemplate jdbc=mock(JdbcTemplate.class);doThrow(new DuplicateKeyException("duplicate")).when(jdbc).update(startsWith("INSERT INTO event_consume_log"),(Object[])any());SearchService service=new SearchService(es,jdbc,new ObjectMapper(),mock(RabbitTemplate.class),"http://product","key");service.consume("{\"eventId\":\"event-1\",\"eventType\":\"product.spu.on-sale.v1\",\"aggregateId\":\"10001\",\"payload\":{\"id\":10001}}");verifyNoInteractions(es);}}
